    for c in range(cols):
        if demo_input_rows[r][c] == 6:
            left = demo_input_rows[r][c-1] if c > 0 else None
            right = demo_input_rows[r][c+1] if c < cols-1 else None
            if left != 6 and right != 6:
                isolated_6s.append((r, c))

print(f"Isolated 6s (no horizontal 6 neighbor): {len(isolated_6s)}")
print(f"First 10: {isolated_6s[:10]}")

# Check if isolated 6s stay 6
isolated_6s_unchanged = 0
isolated_6s_changed = 0
for r, c in isolated_6s:
    if demo_output_rows[r][c] == 6:
        isolated_6s_unchanged += 1
    else:
        isolated_6s_changed += 1
print(f"Isolated 6s that stayed 6: {isolated_6s_unchanged}")
print(f"Isolated 6s that changed to 8: {isolated_6s_changed}")
