# So the complete rule is:
# - If a cell has value 0: output = 0 (always)
# - If a cell has value 6 and has horizontal neighbor also 6: output = 8
# - If a cell has value 6 and NO horizontal neighbor is 6: output = 6

print("\n=== Rule Verification ===")
all_correct = True
for r in range(rows):
    for c in range(cols):
        inp = demo_input_rows[r][c]
        out = demo_output_rows[r][c]

