            print(f"FAIL at ({r},{c}): input={inp}, output={out}, expected={expected}")

if all_correct:
    print("Rule is CORRECT!")
    print("6s adjacent to other 6s horizontally → 8")
    print("6s isolated (no horizontal 6 neighbor) → 6")
