# Final verification of the rule and apply to test input
def has_adjacent_same(r, c, grid, val, rows, cols):
    """Check if position (r,c) with value `val` has any adjacent cell also with value `val`"""
    neighbors = []
    if r > 0: neighbors.append((r-1, c))  # up
    if r < rows-1: neighbors.append((r+1, c))  # down
    if c > 0: neighbors.append((r, c-1))  # left
    if c < cols-1: neighbors.append((r, c+1))  # right

    for nr, nc in neighbors:
        if grid[nr][nc] == val:
            return True
    return False

