    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 0, 7, 0, 7, 7, 7, 7, 0, 0, 7, 7, 7]
]

rows = len(test_input)
cols = len(test_input[0])

def apply_transformation(grid):
    output = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                output[r][c] = 0  # 0s always stay 0
            else:
                if has_adjacent_same(r, c, grid, val, rows, cols):
                    output[r][c] = 8  # non-zero adjacent to same value → 8
                else:
                    output[r][c] = val  # isolated non-zero stays same
    return output

